import string

def is_printable(text):
    return all(c in string.printable for c in text)

# Load the ciphertext
with open('encrypted', 'r') as f:
    hex_str = f.read().strip()
ciphertext = bytes.fromhex(hex_str)

# Method 1: XOR with previous byte of ciphertext (not decrypted)
def xor_with_prev(data, initial_key):
    result = bytearray()
    prev = initial_key

    for b in data:
        decrypted = b ^ prev
        result.append(decrypted)
        prev = b

    return bytes(result)

# Method 2: XOR with running XOR of all previous bytes
def xor_with_running_xor(data, initial_key):
    result = bytearray()
    running_xor = initial_key

    for b in data:
        decrypted = b ^ running_xor
        result.append(decrypted)
        running_xor ^= b

    return bytes(result)

# Method 3: XOR with previous decrypted byte
def xor_with_prev_decrypted(data, initial_key):
    result = bytearray()
    prev = initial_key

    for b in data:
        decrypted = b ^ prev
        result.append(decrypted)
        prev = decrypted

    return bytes(result)

# Method 4: XOR with position-dependent key (Vigenère-like)
def xor_with_position(data, key):
    result = bytearray()
    for i, b in enumerate(data):
        result.append(b ^ key[i % len(key)])
    return bytes(result)

print('Trying different XOR methods with promising initial keys...')

# Define some potential keys based on 'A quark' which showed promise
